import {BENCHMARKS,validateBenchmarkReport,summarizeReport} from './benchmarks.js';
import {catalog,dimensions,evidenceFor,reviewedOn,documentSummary} from './technology.js';
import {demo,clone,TYPES,validateState,platformMetrics,scorePlatforms,decision,normalizedMix} from './core.js';
const KEY='basis-iris-production-v1';
const EVALUATION_KEYS=[KEY,'basis-latest-agent-result','basis-community-benchmark-imports','basis-swe-config','basis-evaluation-repo','basis-evidence-exclusions'];
let s;try{s=JSON.parse(localStorage.getItem(KEY));if(!validateState(s))throw Error('Invalid');}catch{s=clone(demo)}
let page='overview',filter='All',selected=s.platforms[0]?.id,drawer=false,details=false,notice='';
const $=x=>document.querySelector(x);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const f=(x,d=0)=>x==null?'—':Number(x).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});const money=x=>x==null?'—':'$'+f(x,0);const pct=x=>x==null?'—':f(x*100,1)+'%';const safeHref=u=>/^https:\/\/[^\s]+$/i.test(String(u||''))?esc(u):'#';const icon=(n,size=18)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><use href="#i-${n}"></use></svg>`;
const icons=`<svg width="0" height="0" style="position:absolute;overflow:hidden"><defs>${Object.entries({play:'<path d="m8 5 11 7-11 7Z"/>',spark:'<path d="m12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',finger:'<path d="M12 11v3m-4-2v2a4 4 0 0 0 8 0v-2a4 4 0 1 0-8 0ZM5 13V9a7 7 0 0 1 14 0v4M3 15V9a9 9 0 0 1 18 0v6M12 19v2"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8-9 10-5.5-2-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',flask:'<path d="M9 3h6m-5 0v6l-5.6 9.5A2 2 0 0 0 6 21h12a2 2 0 0 0 1.6-2.5L14 9V3M7 16h10"/>',bars:'<path d="M5 20V10m7 10V4m7 16v-7"/>',scale:'<path d="M12 3v18M5 7h14M5 7 2 13h6L5 7Zm14 0-3 6h6l-3-6ZM8 21h8"/>',brain:'<path d="M12 18V6a4 4 0 0 0-8 0 4 4 0 0 0-1 7 4 4 0 0 0 4 6 4 4 0 0 0 5-1Zm0 0V6a4 4 0 0 1 8 0 4 4 0 0 1 1 7 4 4 0 0 1-4 6 4 4 0 0 1-5-1Z"/>',chev:'<path d="m9 18 6-6-6-6"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m4 12 5 5L20 6"/>',warning:'<path d="m12 3 10 18H2L12 3Zm0 7v4m0 3h.01"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',download:'<path d="M12 3v14m-5-5 5 5 5-5M4 17v4h16v-4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',trash:'<path d="M4 7h16M10 7V4h4v3m-8 0 1 14h10l1-14M10 11v6m4-6v6"/>',link:'<path d="M10 14a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 10a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',book:'<path d="M4 5h7a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4zM20 5h-4a3 3 0 0 0-3 3v13a3 3 0 0 1 3-3h4z"/>',rotate:'<path d="M3 12a9 9 0 1 0 3-7M3 4v5h5"/>',cross:'<path d="M5 5l14 14m0-14L5 19"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'}).map(([n,d])=>`<g id="i-${n}">${d}</g>`).join('')}</defs></svg>`;
function save(){s.meta.lastUpdated=new Date().toISOString().slice(0,10);localStorage.setItem(KEY,JSON.stringify(s));}function note(t){notice=t;render();setTimeout(()=>{notice='';const n=$('#toast');if(n)n.remove()},3200)}
const nav=[['overview','Home','grid'],['org','Team context','finger'],['pilot','Tasks','flask'],['gates','Services & criteria','shield'],['record','Run evaluation','play'],['pilotResults','Pilot results','book'],['results','Evaluation results','bars'],['compare','Pilot comparison','bars'],['technology','Tool catalog','book'],['benchmarks','External benchmarks','book'],['judge','Review quality','shield'],['decision','Decision summary','scale'],['settings','Settings','settings']];
const stages=[
 {label:'Set up',icon:'settings',pages:['org','pilot','gates'],hint:'Describe your team, define tasks, then configure services and evaluation criteria.'},
 {label:'Run evaluation',icon:'play',pages:['record'],hint:'Review setup, add optional benchmarks, and execute locally.'},
 {label:'Results',icon:'bars',pages:['results'],hint:'Inspect saved runs, compare evidence, and review requirements.'}
];
function stageFor(id){return stages.find(g=>g.pages.includes(id))}
function sidebarNav(){const items=[['overview','Home','grid'],...stages.map(g=>[g.pages[0],g.label,g.icon]),['technology','Tool catalog','book'],['settings','Settings','settings']];return items.map(([id,label,i],n)=>`${n===4?'<div class="sidetitle nav-resources">RESOURCES</div>':''}<button class="navitem ${(page===id||stageFor(id)?.pages.includes(page))?'active':''}" data-nav="${id}" ${(page===id||stageFor(id)?.pages.includes(page))?'aria-current="page"':''}>${icon(i,18)}<span>${label}</span></button>`).join('')}
function stageNavigation(){const g=stageFor(page);if(!g)return '';return `<div class="stage-navigation"><nav aria-label="${g.label} sections">${g.pages.map(id=>`<button data-nav="${id}" ${id===page?'aria-current="page"':''} class="${id===page?'chosen':''}">${esc(nav.find(n=>n[0]===id)[1])}</button>`).join('')}</nav><p>${g.hint}</p></div>`}
function storedEvidence(){let agent=null,reports=[];try{agent=JSON.parse(localStorage.getItem('basis-latest-agent-result')||'null')}catch{}try{const data=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]');if(Array.isArray(data))reports=data}catch{}return {agent,reports}}

function shell(content){return `${icons}<div class="shell"><aside class="side ${drawer?'show':''}"><div class="brand"><svg class="brand-symbol" aria-hidden="true" viewBox="0 0 48 48"><path d="M24 9v30M9 24h30M13.4 13.4l21.2 21.2m0-21.2L13.4 34.6" fill="none" stroke="#bc9cef" stroke-width="3.4"/></svg><div><b>basis<span class="dot">.</span></b></div></div><div class="sidetitle">EVALUATION</div><nav aria-label="Main navigation">${sidebarNav()}</nav><div class="sidebottom"><div class="smallcaps">CURRENT EVALUATION</div><strong>${esc(s.meta.name)}</strong><div class="tiny">${s.platforms.filter(x=>x.enabled).length} candidates · ${s.runs.length} pilot records</div><div class="sideactions"><button title="Export study" data-act="export">${icon('download',16)}</button><button title="Import study" data-act="import">${icon('upload',16)}</button><button title="Reset local evaluation" aria-label="Reset local evaluation" data-act="reset">${icon('rotate',16)}</button></div></div></aside><main class="main"><header class="top"><button class="mobilemenu" data-act="menu" aria-label="Toggle menu">${icon('menu')}</button><div class="crumb">WORKSPACE <span>/</span> ${esc(stageFor(page)?.label||nav.find(x=>x[0]===page)?.[1])}</div><div class="topright"><span class="studyflag ${s.meta.demo?'demo':''}">${s.meta.demo?'● DEMONSTRATION DATA':'● RECORDED DATA (UNVERIFIED)'}</span><button class="helpbtn" data-act="assistant" aria-label="Help">${icon('info',16)} <span>Help</span></button></div></header><div class="workspace">${stageNavigation()}${content}</div><footer>Basis / Evidence before preference <span>Setup stays in this browser · Local runs stay on this computer</span></footer></main></div>${drawer?'<button class="backdrop" data-act="menu" aria-label="Close menu"></button>':''}${notice?`<div id="toast" role="status">${esc(notice)}</div>`:''}<input type="file" id="file-input" accept=".json,application/json" hidden>`}
function title(k,h,desc,action=''){const group=stageFor(page);if(group)k=`0${stages.indexOf(group)+1} / ${group.label.toUpperCase()}`;return `<div class="eyebrow"><span class="pin"></span>${k}</div><div class="pageheading"><div><h1>${h}</h1><p>${desc}</p></div>${action}</div>`}
function platformName(id){return s.platforms.find(p=>p.id===id)?.name||id}function selectOptions(items,v){return items.map(([value,text])=>`<option value="${esc(value)}" ${String(value)===String(v)?'selected':''}>${esc(text)}</option>`).join('')}
function stat(v,l,d){return `<div class="metric"><div class="m-label">${l}</div><strong>${v}</strong><span>${d}</span></div>`}
function overview(){
 const {reports}=storedEvidence(),hasEvidence=!!(s.runs.length||reports.length);
 return title('START HERE','Compare coding tools, step by step.','Prepare your evaluation, collect results, and compare the evidence.')+`
 <section class="start-panel"><div class="start-copy"><span class="miniTag">Your evaluation</span><h2>Start with your team’s work</h2><p>Choose the services you want to evaluate and define what successful work looks like.</p><button class="primary" data-nav="org">Set up an evaluation ${icon('chev',16)}</button></div><ol class="start-checklist"><li><span>1</span><div><b>Set up</b><small>Select services, requirements, tasks, and credentials.</small></div></li><li><span>2</span><div><b>Run evaluation</b><small>Execute tasks and optional benchmarks locally.</small></div></li><li><span>3</span><div><b>Review results</b><small>Compare services against the criteria you defined.</small></div></li></ol></section>
 <div class="journey-grid"><button class="journey-card" data-nav="org"><span class="journey-number">01 / SET UP</span><h3>Prepare your evaluation</h3><p>Define your team context, requirements, and tasks.</p><span class="journey-link">Open setup ${icon('chev',16)}</span></button><button class="journey-card" data-nav="record"><span class="journey-number">02 / RUN EVALUATION</span><h3>Collect real evidence</h3><p>Execute tasks and optional benchmark packs locally.</p><span class="journey-link">Open Run evaluation ${icon('chev',16)}</span></button><button class="journey-card" data-nav="results"><span class="journey-number">03 / RESULTS</span><h3>Review what happened</h3><p>${hasEvidence?'Review recorded observations and benchmark reports.':'Run an evaluation to compare service outcomes against your saved setup.'}</p><span class="journey-link">Open results ${icon('chev',16)}</span></button></div>`;
}

function profileValue(path){const [group,key]=path.split('.');const value=s[group][key];return !s.meta.editedFields?.includes(path)&&value===demo[group][key]?'':esc(value)}
function org(){const o=s.org;return title('02 / CONTEXT','Team context','Describe the team and workload you want to evaluate.',`<button class="secondary" data-act="assistant">${icon('spark',16)} Guided discovery</button>`)+`<div class="split"><div class="panel"><div class="panelheading"><h3>Organization profile</h3><span class="miniTag">Editable</span></div><div class="formgrid"><label>Organization<input data-path="meta.name" placeholder="New organization study" value="${profileValue('meta.name')}"></label><label>Engineers<input type="number" min="1" data-path="org.developers" placeholder="0" value="${profileValue('org.developers')}"></label><label>Blended hourly cost ($)<input type="number" min="0" data-path="org.rate" placeholder="0" value="${profileValue('org.rate')}"></label><label>Monthly AI budget ($)<input type="number" min="0" data-path="org.budget" placeholder="0" value="${profileValue('org.budget')}"></label><label>Risk profile<select data-path="org.risk" data-placeholder-value="unassessed">${selectOptions([['unassessed','Select risk profile'],['high','High governance'],['medium','Standard governance'],['low','Experimental']],o.risk)}</select></label><label>Repository profile<input data-path="org.repoSize" placeholder="Not provided" value="${profileValue('org.repoSize')}"></label></div><label class="fullfield">Languages / frameworks (comma separated)<input data-path="org.stack" placeholder="e.g. TypeScript, Python, React" value="${esc(o.stack.join(', '))}"></label><label class="fullfield">Primary objective<textarea data-path="org.objective" placeholder="Describe what you want to improve">${profileValue('org.objective')}</textarea></label><label class="fullfield">Data boundaries<textarea data-path="org.privacy" placeholder="Describe your data and privacy requirements">${profileValue('org.privacy')}</textarea></label></div><div class="panel"><div class="panelheading"><h3>Workload signature</h3><span class="miniTag">Adjust the mix</span></div><p class="muted">How is your team's engineering time distributed? These weights drive the task-adjusted comparisons.</p><div class="mixbars">${TYPES.map((t,i)=>`<div class="mixrow"><div class="mixhead"><span><i class="mixdot" style="background:var(--c${i+1})"></i>${t}</span><b data-mix-label="${t}">${s.mix[t]}%</b></div><input aria-label="${t} workload share" type="range" min="0" max="100" data-mix="${t}" value="${s.mix[t]}" style="accent-color:var(--c${i+1})"></div>`).join('')}</div><div class="panelnote" id="mixnote">Normalized for comparison: ${Math.round(Object.values(s.mix).reduce((a,b)=>a+Number(b),0))}% entered (automatically normalized).</div><div class="miniCall">${icon('info',18)} <span>Profile inputs are self-reported unless verified by linked evidence. No repository has been analyzed.</span></div></div></div><div class="panel focus"><h3>Decision priorities</h3><p class="muted">Weights influence exploratory scores. Required gates cannot be overridden by a high score.</p><div class="weightrow">${Object.entries(s.weights).map(([k,v])=>`<label>${k[0].toUpperCase()+k.slice(1)} <input type="number" min="0" max="100" data-weight="${k}" value="${v}"> <small>%</small></label>`).join('')}</div><button class="primary" data-nav="pilot">Define tasks ${icon('chev',16)}</button></div>`}
const pendingKeys=new Map();
const isLocalApp=()=>['localhost','127.0.0.1'].includes(location.hostname);
function serviceKey(p){return p.id==='opencode'?(modelProvider(p)==='anthropic'?'ANTHROPIC_API_KEY':'OPENAI_API_KEY'):localRunners[p.id]||null}
function serviceKeyField(p){const key=serviceKey(p);return key?`<div class="service-key-field"><div class="key-field-heading"><label for="key-${esc(p.id)}">API key</label><span class="pill unverified" data-key-status="${key}">Checking…</span></div><div class="credential-entry"><input id="key-${esc(p.id)}" type="password" aria-label="${esc(p.name)} API key" autocomplete="new-password" data-local-key="${key}" placeholder="API key" ${isLocalApp()?'disabled':''}>${isLocalApp()?`<button class="secondary" data-save-local="${key}" disabled>Save key</button>`:''}</div><p class="credential-feedback" role="status" data-key-feedback="${key}"></p></div>`:`<p class="service-config-note">${p.id==='opencode'?'Choose a provider/model to configure its key.':'Automatic execution is not available for this service.'}</p>`}
function setupHandoff(){if(page==='pilot')return `<div class="setup-handoff"><div><b>Next: services & criteria</b><p class="muted">Choose the services that will attempt your tasks.</p></div><button class="primary" data-nav="gates">Configure services ${icon('chev',16)}</button></div>`;return `<div class="setup-handoff"><div><b>${isLocalApp()?'Your setup stays on this device':'Take your setup to the local app'}</b><p class="muted">${isLocalApp()?'Saved keys are reused automatically.':'Services, tasks, and prepared keys move together.'}</p></div><div class="inlineactions">${page==='gates'?'<button class="secondary" data-nav="pilot">Review tasks</button>':''}<button class="primary" data-act="continue-local">${isLocalApp()?'Continue to evaluation':'Continue locally'} ${icon('chev',16)}</button></div><p id="handoff-feedback" role="status"></p></div>`}
const modelCatalogs=new Map();
function modelProvider(p){return p.id==='opencode'?(p.modelProvider|| (p.model?.startsWith('anthropic/')?'anthropic':'openai')):({codex:'openai',claude:'anthropic',cursor:'cursor'}[p.id]||'');}
function modelCatalogKey(p){return p.id+':'+modelProvider(p);}
function serviceModelField(p){
 const supported=!!modelProvider(p),catalog=modelCatalogs.get(modelCatalogKey(p));
 const connected=isLocalApp()&&bridgeReady&&localStatus?.configured?.[serviceKey(p)];
 const ready=connected&&catalog?.status==='ready'&&catalog.models.length>0;
 const current=/^Specify /.test(p.model||'')?'':p.model||'';
 const listed=ready&&catalog.models.some(m=>m.id===current);
 const placeholder=!supported?'Managed by service':!isLocalApp()?'Continue locally to load models':!connected?'Save a key first':catalog?.status==='loading'?'Loading models…':catalog?.status==='error'?'Models unavailable':catalog?.status==='ready'&&!catalog.models.length?'No models returned':'Select a model';
 const message=catalog?.status==='error'?catalog.error:ready&&current&&!listed?'Previous selection is unavailable. Choose a returned model.':'';
 return `<div class="model-field-heading"><label for="model-${esc(p.id)}">Model</label>${supported?`<button class="iconbtn" type="button" data-refresh-models="${esc(p.id)}" aria-label="Refresh ${esc(p.name)} models" title="${esc(catalog?.fetchedAt?`Fetched from ${catalog.source} at ${catalog.fetchedAt}. Refresh models.`:'Refresh models')}" ${!connected||catalog?.status==='loading'?'disabled':''}>${icon('rotate',14)}</button>`:''}</div><select id="model-${esc(p.id)}" data-service-model="${esc(p.id)}" aria-label="${esc(p.name)} model" data-placeholder-value="" ${!ready?'disabled':''}><option value="" disabled ${!listed?'selected':''}>${esc(placeholder)}</option>${ready?catalog.models.map(m=>`<option value="${esc(m.id)}" ${m.id===current?'selected':''}>${esc(m.name===m.id?m.id:m.name+' · '+m.id)}</option>`).join(''):''}</select><p class="model-feedback" role="status">${esc(message)}</p>`;
}
function paintModelFields(){
 if(activeDropdown?.trigger?.closest('[data-model-control]'))closeDropdown();
 document.querySelectorAll('[data-model-control]').forEach(holder=>{const p=s.platforms.find(p=>p.id===holder.dataset.modelControl);if(p)holder.innerHTML=serviceModelField(p)});
 enhanceSelects();bindModelFields();
}
function bindModelFields(){
 document.querySelectorAll('[data-service-model]').forEach(el=>el.onchange=()=>{const p=s.platforms.find(p=>p.id===el.dataset.serviceModel),catalog=modelCatalogs.get(modelCatalogKey(p));if(catalog?.status==='ready'&&catalog.models.some(m=>m.id===el.value)){p.model=el.value;save();const feedback=el.closest('[data-model-control]')?.querySelector('.model-feedback');if(feedback)feedback.textContent=''}});
 document.querySelectorAll('[data-refresh-models]').forEach(el=>el.onclick=()=>loadServiceModels(s.platforms.find(p=>p.id===el.dataset.refreshModels),true));
 document.querySelectorAll('[data-model-provider]').forEach(el=>el.onchange=()=>{const p=s.platforms.find(p=>p.id===el.dataset.modelProvider);p.modelProvider=el.value;p.model='';save();render()});
}
async function loadServiceModels(p,force=false){
 const key=modelCatalogKey(p),existing=modelCatalogs.get(key);
 if(!modelProvider(p)||!isLocalApp()||!bridgeReady||!localStatus?.configured?.[serviceKey(p)])return;
 if(!force&&existing&&(existing.status==='loading'||Date.now()-existing.time<60000))return;
 const entry={status:'loading',models:[],time:Date.now()};modelCatalogs.set(key,entry);paintModelFields();
 try{const result=await localRequest('models',{service:p.id,provider:modelProvider(p)});if(!Array.isArray(result.models))throw Error('Update and restart the local companion to load models.');if(modelCatalogs.get(key)!==entry)return;Object.assign(entry,result,{status:'ready',time:Date.now()});}
 catch(error){if(modelCatalogs.get(key)!==entry)return;Object.assign(entry,{status:'error',error:error.message,models:[],time:Date.now()})}
 paintModelFields();if(page==='record')refreshEvaluationReadiness();
}
function invalidateModels(secret){const provider={OPENAI_API_KEY:'openai',ANTHROPIC_API_KEY:'anthropic',CURSOR_API_KEY:'cursor'}[secret];for(const key of modelCatalogs.keys())if(key.endsWith(':'+provider))modelCatalogs.delete(key);paintModelFields();}
function serviceSelection(){return `<section class="panel service-selection" aria-labelledby="services-heading"><div class="panelheading"><div><span class="smallcaps">1 / SERVICES</span><h3 id="services-heading">Models & keys</h3></div><button class="secondary" data-act="manage-platforms">${icon('plus',16)} Add custom service</button></div><div class="service-configurations">${s.platforms.filter(p=>p.enabled).map(p=>`<section class="service-configuration" data-config-service="${esc(p.id)}" aria-label="${esc(p.name)} configuration"><div class="service-config-heading"><div><h3>${esc(p.name)}</h3><span class="muted">${esc(p.provider||'Custom service')}</span></div><button class="iconbtn" type="button" data-act="toggle-service" data-id="${esc(p.id)}" aria-pressed="true" aria-label="Remove ${esc(p.name)} from evaluation" title="Remove service">${icon('cross',16)}</button></div>${p.id==='opencode'?`<label class="model-provider">Provider<select data-model-provider="opencode" aria-label="OpenCode provider">${selectOptions([['openai','OpenAI'],['anthropic','Anthropic']],modelProvider(p))}</select></label>`:''}<div class="service-config-fields"><div data-service-key="${esc(p.id)}">${serviceKeyField(p)}</div><div class="service-model-field" data-model-control="${esc(p.id)}">${serviceModelField(p)}</div></div></section>`).join('')||'<p class="muted">Choose a service below to get started.</p>'}</div><div class="available-services">${s.platforms.filter(p=>!p.enabled).map(p=>`<button class="secondary" data-act="toggle-service" data-id="${esc(p.id)}" aria-pressed="false" aria-label="Include ${esc(p.name)} in evaluation">${icon('plus',14)} ${esc(p.name)}</button>`).join('')}</div><div class="service-config-footer"><span class="muted">${isLocalApp()?'Keys are shared with Settings.':'Keys stay in memory until you continue locally.'}</span>${isLocalApp()?`<button class="iconbtn" id="bridge-recheck" aria-label="Check connection" title="Check connection">${icon('rotate',16)}</button>`:''}<button class="inlinebtn" data-act="connection-help">Connection help</button></div></section>`}
function continueLocally(){
 if(isLocalApp()){page='record';render();return}
 // Include unsaved visible entries, so the handoff never silently drops a typed key.
 document.querySelectorAll('[data-local-key]').forEach(input=>{if(input.value.trim())pendingKeys.set(input.dataset.localKey,input.value.trim())});
 const allowed=new Set(neededProviders().map(p=>p.secret));
 const keys=Object.fromEntries([...pendingKeys].filter(([key])=>allowed.has(key)));
 if(Object.values(keys).some(value=>value.length<8||value.length>8000||/[\r\n\x00]/.test(value))){showMessage('Enter a valid single-line API key before continuing.');return}
 const targetOrigin='http://127.0.0.1:8765',nonce=Array.from(crypto.getRandomValues(new Uint32Array(4)),x=>x.toString(16).padStart(8,'0')).join('');
 let popup,timeout,complete=false;
 const feedback=message=>{if($('#handoff-feedback'))$('#handoff-feedback').textContent=message};
 const cleanup=()=>{clearTimeout(timeout);window.removeEventListener('message',receive)};
 const receive=event=>{if(event.origin!==targetOrigin||event.source!==popup||event.data?.nonce!==nonce)return;
  if(event.data.type==='basis-setup-ready'&&!complete){complete=true;popup.postMessage({type:'basis-setup-transfer',nonce,setup:clone(s),keys},targetOrigin);feedback('Finish in the local app.');clearTimeout(timeout)}
  if(event.data.type==='basis-setup-complete'){pendingKeys.clear();document.querySelectorAll('[data-local-key]').forEach(input=>input.value='');updateLocalStatus();feedback('Setup transferred. Continue in the local app.');cleanup()}
  if(event.data.type==='basis-setup-error'){feedback('Transfer was not completed. Your setup is still here.');cleanup()}
 };
 window.addEventListener('message',receive);
 popup=window.open(`${targetOrigin}/#setup-transfer=${nonce}`,'_blank');
 if(!popup){cleanup();feedback('Allow the local-app window, then try again.');return}
 feedback('Opening the local app…');
 timeout=setTimeout(()=>{cleanup();feedback('Local app not available. Start it using Connection help, then try again.');},15000);
}
function receiveLocalSetup(){
 if(!isLocalApp()||!window.opener)return;
 const nonce=new URLSearchParams(location.hash.slice(1)).get('setup-transfer');
 if(!/^[a-f0-9]{4,128}$/.test(nonce||''))return;
 history.replaceState(null,'',location.pathname+location.search);
 const source=window.opener,origin='https://pouyanjay.github.io';let processing=false;
 const reply=type=>source.postMessage({type,nonce},origin);
 const receive=async event=>{if(processing||event.source!==source||event.origin!==origin||event.data?.nonce!==nonce||event.data.type!=='basis-setup-transfer')return;
  processing=true;clearInterval(readyTimer);window.removeEventListener('message',receive);
  try{const {setup,keys}=event.data;if(!validateState(setup)||!setup.meta||setup.meta.demo||!keys||typeof keys!=='object'||Array.isArray(keys))throw Error('Invalid setup transfer.');
   const allowed=new Set(localProviders.map(p=>p.secret));
   if(Object.entries(keys).some(([key,value])=>!allowed.has(key)||typeof value!=='string'||value.length<8||value.length>8000||/[\r\n\x00]/.test(value)))throw Error('Invalid credential transfer.');
   if((s.meta.name!==demo.meta.name||s.execution||['org','platforms','tasks','runs','gates','gateResults','mix','weights','assumptions'].some(key=>JSON.stringify(s[key])!==JSON.stringify(demo[key])))&&!await confirmDialog('Use the incoming setup in this browser? Saved local evaluations will be kept.',{title:'Replace local setup?',confirmLabel:'Use incoming setup'})){reply('basis-setup-error');return}
   await checkBridge();if(!bridgeReady)throw Error('Connect to the local app and try again.');
   for(const [secret,value] of Object.entries(keys))await localRequest('credentials',{secret,value});
   s=setup;save();page='gates';render();reply('basis-setup-complete');note('Setup ready. Keys saved on this device.');
  }catch(error){reply('basis-setup-error');showMessage(error.message)}
 };
 window.addEventListener('message',receive);reply('basis-setup-ready');
 const readyTimer=setInterval(()=>reply('basis-setup-ready'),500);
 setTimeout(()=>{clearInterval(readyTimer);if(!processing)window.removeEventListener('message',receive)},15000);
}

function gates(){return title('03 / TRUST','Services & criteria','Configure your services, then review what they need to meet.','')+serviceSelection()+`<div class="panel requirements-panel"><div class="panelheading"><div><span class="smallcaps">2 / REQUIREMENTS</span><h3>Evaluation criteria</h3></div><button class="secondary" data-act="add-gate">${icon('plus',16)} Add requirement</button></div><p class="muted">Leave a requirement unverified when it still needs evaluation.</p>${s.platforms.some(p=>p.enabled)?'<div class="table-scroll">':'<div class="empty"><b>No services selected</b><p>Include a service above or add your own to begin checking requirements.</p></div><div hidden>'}<table><thead><tr><th>Requirement</th>${s.platforms.filter(p=>p.enabled).map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${s.gates.map(g=>`<tr><th><span class="gate-title">${icon('shield',16)} ${esc(g.name)}</span><small>${g.required?'Mandatory':'Advisory'} · <button class="inlinebtn" data-act="delete-gate" data-id="${g.id}">Remove</button></small></th>${s.platforms.filter(p=>p.enabled).map(p=>`<td data-service-label="${esc(p.name)}"><select class="status ${s.gateResults[p.id]?.[g.id]||'unverified'}" aria-label="${esc(p.name)}: ${esc(g.name)}" data-gate="${p.id}:${g.id}">${selectOptions([['unverified','? Unverified'],['pass','✓ Pass'],['fail','× Fail']],s.gateResults[p.id]?.[g.id]||'unverified')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panelnote">Always attach documentary proof during real evaluation. A marked pass without a verified source is a self-reported claim.</div></div>${setupHandoff()}`;}
function editTask(task=null){addModal(task?'Edit task':'Define task',[
 {name:'name',label:'Task name'},{name:'type',label:'Work type',type:'select',options:TYPES.map(x=>[x,x])},
 {name:'difficulty',label:'Difficulty',type:'select',options:[['easy','Easy'],['medium','Medium'],['hard','Hard']]},
 {name:'acceptance',label:'Independent acceptance criteria'},
 {name:'sourcePath',label:'Source folder (absolute path; blank starts empty)',required:false},
 {name:'checksPath',label:'Independent checks folder (mounted read-only at /checks)',required:false},
 {name:'checkCommand',label:'Check command, e.g. python3 /checks/test_solution.py',required:false},
 {name:'baseline',label:'Baseline human minutes',type:'number',min:0,value:60}
 ].map(field=>({...field,value:task?.[field.name]??field.value})),values=>{const updated={...values,baseline:Number(values.baseline)};if(task)Object.assign(task,updated);else s.tasks.push({id:'T-'+Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16).padStart(8,'0')).join(''),...updated})})}
function fairGuideButton(){return `<button class="secondary" data-act="fair-guide">${icon('book',16)} Fair testing guide</button>`;}
function pilot(){return title('01 / SET UP','Tasks','Define the work each service will attempt and the criteria for accepting its result.',`<div class="inlineactions">${fairGuideButton()}<button class="primary" data-act="add-task">${icon('plus',16)} Add task</button></div>`)+`${s.tasks.length?'':'<div class="empty"><b>No tasks yet</b><p>Add a task with clear acceptance criteria and an estimate of human effort without the tool.</p></div>'}<div class="taskgrid">${s.tasks.map(t=>`<div class="panel task"><div class="smallcaps">${esc(t.id)} · ${esc(t.type)}</div><h3>${esc(t.name)}</h3><p>${esc(t.acceptance)}</p><p class="muted">${t.sourcePath?`Source: ${esc(t.sourcePath)}`:'Starts in an empty workspace'} · ${t.checkCommand?'Independent checks configured':'Human review required'}</p><div class="taskbottom"><span>${esc(t.difficulty)} · ${f(t.baseline)} min baseline</span><button class="secondary" data-act="edit-task" data-id="${esc(t.id)}">Edit task</button><button class="iconbtn" data-act="delete-task" data-id="${t.id}" title="Delete task">${icon('trash',16)}</button></div></div>`).join('')}</div>${setupHandoff()}`;}
let evaluationHistory=[],evaluationSelected='',evaluationTimer=null,evaluationError='';
function runOptions(){const options=s.execution||{};return {timeoutSeconds:Number.isInteger(options.timeoutSeconds)?options.timeoutSeconds:600,benchmarkPaths:Array.isArray(options.benchmarkPaths)?options.benchmarkPaths.filter(p=>typeof p==='string'):[]}}
function currentEvaluation(){return evaluationHistory.find(j=>j.id===evaluationSelected)||evaluationHistory[0]||null}
function runProgress(job){if(!job)return '<p class="muted">No evaluation has started yet.</p>';return `<div class="panelheading"><h3>${esc(job.message)}</h3><span class="pill">${esc(job.status)}</span></div><progress aria-label="Completed attempts" max="${job.total||1}" value="${job.results.length}"></progress><p class="muted">${job.results.length} of ${job.total} attempts finished</p><div class="inlineactions">${['preparing','running'].includes(job.status)?'<button class="secondary" id="stop-evaluation">Stop evaluation</button>':''}<button class="secondary" data-nav="results">View evaluation results ${icon('chev',16)}</button></div>`}
function record(){const options=runOptions(),services=s.platforms.filter(p=>p.enabled);return title('02 / RUN','Run evaluation','Run the tasks from Set up and optionally add benchmark packs. Each run keeps its own setup and source snapshots.')+localConnection()+`
<section class="panel"><div class="panelheading"><h3>Evaluation from Set up</h3><button class="secondary" data-nav="gates">Edit setup</button></div><div class="statusgrid"><div><b>${services.length} services</b><p>${services.map(p=>esc(p.name)).join(', ')||'None selected'}</p></div><div><b>${s.tasks.length} team tasks</b><p>${s.gates.filter(g=>g.required).length} mandatory requirements</p></div></div><p class="muted">${esc(s.org.objective)}</p><p class="panelnote">Team context and acceptance criteria guide each task. Requirements, workload mix, and decision priorities are saved with the run. Policy and governance requirements still require documentary review.</p><div id="evaluation-readiness" role="status">Checking credentials and Docker…</div></section>
<section class="panel"><h3>Optional benchmarks</h3><div class="benchmark-choice"><b>HumanEval · Python function tasks</b><p class="muted">Historical public benchmark, using pinned original tasks and held-out checks. A deterministic subset runs through Basis’s agent adapter; this is not an official leaderboard score.</p><label>Number of tasks<input id="humaneval-count" type="number" min="1" max="50" value="5"></label><button class="secondary" id="add-humaneval">Add HumanEval</button></div><h3>Local benchmark packs</h3><p class="muted">Add a local pack containing tasks, starting files, and independent checks. Each selected service attempts the same pack. No benchmarks are required to evaluate your own tasks.</p><label class="fullfield">Benchmark pack JSON path<input id="benchmark-pack-path" placeholder="/Users/you/benchmarks/pack.json"></label><button class="secondary" id="add-benchmark-pack">Add benchmark pack</button><div id="benchmark-pack-feedback" role="status"></div><ul class="pack-list">${options.benchmarkPaths.map((p,i)=>`<li><code>${esc(p)}</code><button class="iconbtn" data-remove-pack="${i}" aria-label="Remove benchmark pack">${icon('trash',16)}</button></li>`).join('')}</ul><p class="panelnote">This runs local packs, not official SWE-bench or Terminal-Bench harnesses. Existing official reports can be imported from Results. See README for the pack format and runtime dependencies.</p></section>
<section class="panel"><h3>Execution limits</h3><label class="fullfield">Time limit per agent or check (seconds)<input id="evaluation-timeout" type="number" min="30" max="1800" value="${options.timeoutSeconds}"></label><p class="muted">One attempt per service and task, run sequentially. Each container is limited to 2 CPUs and 2 GB of memory. Provider usage costs are not measured or capped by Basis; your monthly setup budget is context, not an enforced limit.</p><label class="run-consent"><input id="evaluation-consent" type="checkbox"> I authorize provider API usage and sending the chosen source files and task context to the selected providers.</label><button class="primary" id="start-evaluation" disabled>${icon('play',16)} Run evaluation</button><p id="evaluation-error" role="alert">${esc(evaluationError)}</p></section><section class="panel" id="evaluation-progress" aria-live="polite">${runProgress(localStatus?.job)}</section>`}
function excludedSuites(id){try{return JSON.parse(localStorage.getItem('basis-evidence-exclusions')||'{}')[id]||[]}catch{return []}}
function results(){const job=currentEvaluation(),excluded=job?excludedSuites(job.id):[],rows=job?job.results.filter(r=>r.sourceKind!=='benchmark'||!excluded.includes(r.suite)):[];return title('03 / RESULTS','Evaluation results','Review outcomes against the setup saved when the evaluation started.')+localConnection()+`
<div id="results-feedback" role="status">${esc(evaluationError)}</div>${!job?'<section class="empty-results"><h2>No local evaluations loaded</h2><p>Connect the local companion and run an evaluation. Completed and interrupted runs are kept on this computer.</p><button class="primary" data-nav="record">Run evaluation</button></section>':`
<section class="panel"><label>Evaluation<select id="evaluation-history">${evaluationHistory.map(j=>`<option value="${esc(j.id)}" ${j.id===job.id?'selected':''}>${esc(new Date(j.startedAt*1000).toLocaleString())} · ${esc(j.plan?.setup?.meta?.name||'Evaluation')} · ${esc(j.status)}</option>`).join('')}</select></label><p><span class="pill">${esc(job.status)}</span> ${job.results.length} / ${job.total} attempts finished</p><p class="muted">${esc(job.message)}</p><p class="panelnote">Saved locally: <code>${esc(job.folder)}</code>. Source snapshots, agent work, plan.json, and result.json are retained here. Later setup edits do not change this run.</p><button class="secondary" id="export-evaluation">${icon('download',16)} Export results and plan</button></section>
${job.plan.benchmarks.length?`<section class="panel"><h3>Benchmark evidence in this comparison</h3><p class="muted">Include or exclude completed evidence without deleting it. Adding new tests requires a new run.</p>${job.plan.benchmarks.map(b=>`<label class="run-consent"><input type="checkbox" data-include-suite="${esc(b.name)}" ${excluded.includes(b.name)?'':'checked'}> ${esc(b.name)} · ${esc(b.revision)}</label>`).join('')}</section>`:''}
<section class="panel"><h3>Service comparison</h3><p class="muted">Automated checks measure the configured tests, not overall suitability. No score is inferred for missing checks, cost, or human effort.</p><div class="table-scroll"><table><thead><tr><th>Service / model</th><th>Attempts finished</th><th>Checks passed</th><th>Errors / timeouts</th><th>Human acceptance</th></tr></thead><tbody>${job.plan.services.map(p=>{const r=rows.filter(r=>r.agent===p.id),checked=r.filter(r=>r.checkPassed!==null),accepted=r.filter(r=>job.reviews?.[`${r.taskIndex}:${r.agent}`]?.accepted===true);return `<tr><td><b>${esc(p.name)}</b><small>${esc(p.model)}</small></td><td>${r.length}</td><td>${checked.length?`${checked.filter(r=>r.checkPassed).length} / ${checked.length}`:'Not checked'}</td><td>${r.filter(r=>r.status!=='completed').length}</td><td>${accepted.length} accepted / ${r.length}</td></tr>`}).join('')}</tbody></table></div></section>
<section class="panel"><h3>Attempt evidence</h3><div class="evaluation-attempts">${rows.length?rows.map(r=>{const t=job.plan.tasks.find(t=>t.index===r.taskIndex),review=job.reviews?.[`${r.taskIndex}:${r.agent}`];return `<article class="attempt-row"><div><b>${esc(job.plan.services.find(p=>p.id===r.agent)?.name||r.agent)} · ${esc(r.task)}</b><p>${esc(r.suite)} · ${esc(r.status)} · ${f(r.durationSeconds,1)} seconds</p><p>${r.checkPassed===true?'Checks passed':r.checkPassed===false?'Checks failed':'No completed automated check'} · ${review?review.accepted?'Human accepted':'Human rejected':'Awaiting human review'}</p><details><summary>Acceptance criteria and evidence</summary><p>${esc(t.acceptance)}</p><p>Check: <code>${esc(t.checkCommand||'Not configured')}</code></p><p>Agent exit: ${esc(r.agentExitCode??'Unavailable')} · Check exit: ${esc(r.checkExitCode??'Not run')}</p><p>Workspace: <code>${esc(r.folder)}</code></p><p>Usage cost: ${review?.usageCost!=null?money(review.usageCost):'Not measured'} · Human effort: ${review?.humanMinutes!=null?f(review.humanMinutes)+' min':'Not recorded'}</p>${review?`<p>Review: ${esc(review.notes)}</p>`:''}</details></div><button class="secondary" data-review-attempt="${r.taskIndex}:${esc(r.agent)}">Record review</button></article>`}).join(''):'<p class="muted">No attempt evidence in this view yet.</p>'}</div></section>
<section class="panel"><h3>Requirements from the saved setup</h3><p class="muted">These are the assessments at run start. Passing tests does not verify retention, identity, audit, legal, or security controls.</p><div class="table-scroll"><table><thead><tr><th>Requirement</th>${job.plan.services.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${job.plan.setup.gates.map(g=>`<tr><th>${esc(g.name)}<small>${g.required?'Mandatory':'Advisory'}</small></th>${job.plan.services.map(p=>`<td>${esc(job.plan.setup.gateResults?.[p.id]?.[g.id]||'unverified')}<small>Setup assessment; documentary verification required</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><details><summary>Saved team context and decision priorities</summary><pre class="plan-preview">${esc(JSON.stringify({organization:job.plan.setup.org,workload:job.plan.setup.mix,priorities:job.plan.setup.weights},null,2))}</pre></details></section>`}<section class="panel"><h3>Other evidence</h3><p class="muted">Keep existing manual observations and externally generated official reports available for review.</p><div class="inlineactions"><button class="secondary" data-nav="pilotResults">Manual observations</button><button class="secondary" data-nav="benchmarks">Imported benchmark reports</button></div></section>`}
function evaluationReadiness(){const services=s.platforms.filter(p=>p.enabled),problems=[];if(!bridgeReady)problems.push('Start the local companion.');else{if(!localStatus?.dockerReady)problems.push('Start Docker.');if(localStatus?.credentialError)problems.push(localStatus.credentialError);for(const p of services){if(!(p.id in localRunners)){problems.push(`${p.name}: automatic execution is not supported. Remove it from this run in Set up.`);continue}const catalog=modelCatalogs.get(modelCatalogKey(p));if(!catalog||catalog.status!=='ready'||!catalog.models.some(m=>m.id===p.model))problems.push(`${p.name}: choose an available model in Set up.`);const model=p.model||'',key=p.id==='opencode'?(model.startsWith('anthropic/')?'ANTHROPIC_API_KEY':model.startsWith('openai/')?'OPENAI_API_KEY':null):localRunners[p.id];if(!key)problems.push(`${p.name}: set an openai/model or anthropic/model identifier in Set up.`);else if(!localStatus?.configured?.[key])problems.push(`${p.name}: configure ${key} in Credentials.`)}}if(!services.length)problems.push('Select at least one service in Set up.');if(!s.tasks.length&&!runOptions().benchmarkPaths.length)problems.push('Define a task or add a benchmark pack.');if(['preparing','running'].includes(localStatus?.job?.status))problems.push('An evaluation is already running.');return problems}
function refreshEvaluationReadiness(){const issues=evaluationReadiness();if($('#evaluation-readiness'))$('#evaluation-readiness').textContent=issues.length?issues.join(' '):'Ready. Saved credentials will be reused.';if($('#start-evaluation'))$('#start-evaluation').disabled=!!issues.length||!$('#evaluation-consent')?.checked;}
async function loadEvaluationHistory(){const result=await localRequest('evaluations');evaluationHistory=result.evaluations;}
function bindEvaluationProgress(){document.querySelectorAll('#evaluation-progress [data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;render()});$('#stop-evaluation')?.addEventListener('click',async()=>{try{localStatus.job=(await localRequest('stop')).job;await pollEvaluation()}catch(error){evaluationError=error.message;if($('#evaluation-error'))$('#evaluation-error').textContent=error.message}})}
async function pollEvaluation(){clearTimeout(evaluationTimer);if(!['record','results'].includes(page)||!bridgeReady)return;try{localStatus.job=(await localRequest('job')).job;if(page==='record'&&$('#evaluation-progress')){$('#evaluation-progress').innerHTML=runProgress(localStatus.job);bindEvaluationProgress();refreshEvaluationReadiness()}if(page==='results'){const previous=JSON.stringify(evaluationHistory);await loadEvaluationHistory();if(previous!==JSON.stringify(evaluationHistory)){render();return}}}catch(error){if($('#evaluation-error'))$('#evaluation-error').textContent=error.message;else if($('#results-feedback'))$('#results-feedback').textContent=error.message}evaluationTimer=setTimeout(pollEvaluation,2500)}
async function bindEvaluation(){clearTimeout(evaluationTimer);await checkBridge();if(!['record','results'].includes(page))return;refreshEvaluationReadiness();if(bridgeReady){try{const previous=JSON.stringify(evaluationHistory);await loadEvaluationHistory();if(page==='results'&&previous!==JSON.stringify(evaluationHistory)){render();return}}catch(error){evaluationError=error.message}}$('#bridge-recheck')?.addEventListener('click',()=>{evaluationError='';render()});$('#evaluation-consent')?.addEventListener('change',refreshEvaluationReadiness);
$('#evaluation-timeout')?.addEventListener('change',e=>{s.execution={...runOptions(),timeoutSeconds:Number(e.target.value)};save()});
$('#add-humaneval')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;const feedback=$('#benchmark-pack-feedback');feedback.textContent='Downloading and checking the pinned benchmark dataset…';try{const {path,benchmark}=await localRequest('prepare-humaneval',{count:Number($('#humaneval-count').value)});s.execution={...runOptions(),benchmarkPaths:[...runOptions().benchmarkPaths.filter(p=>!p.includes('human-eval-')),path]};save();note(`Added ${benchmark.tasks.length} HumanEval tasks`)}catch(error){feedback.textContent=error.message;if($('#add-humaneval'))$('#add-humaneval').disabled=false}});
$('#add-benchmark-pack')?.addEventListener('click',async()=>{const path=$('#benchmark-pack-path').value.trim(),feedback=$('#benchmark-pack-feedback');try{const {benchmark}=await localRequest('benchmark',{path});if(!runOptions().benchmarkPaths.includes(path)){s.execution={...runOptions(),benchmarkPaths:[...runOptions().benchmarkPaths,path]};save()}note(`Added ${benchmark.name}: ${benchmark.tasks.length} tasks`)}catch(error){feedback.textContent=error.message}});
document.querySelectorAll('[data-remove-pack]').forEach(b=>b.onclick=()=>{s.execution={...runOptions(),benchmarkPaths:runOptions().benchmarkPaths.filter((_,i)=>i!==Number(b.dataset.removePack))};save();render()});
$('#start-evaluation')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;evaluationError='';try{localStatus.job=(await localRequest('run',{plan:{setup:clone(s),...runOptions()},consent:$('#evaluation-consent').checked})).job;evaluationSelected=localStatus.job.id;render()}catch(error){evaluationError=error.message;$('#evaluation-error').textContent=error.message;refreshEvaluationReadiness()}});
$('#evaluation-history')?.addEventListener('change',e=>{evaluationSelected=e.target.value;render()});
$('#export-evaluation')?.addEventListener('click',()=>{const job=currentEvaluation(),url=URL.createObjectURL(new Blob([JSON.stringify(job,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`basis-evaluation-${job.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
document.querySelectorAll('[data-include-suite]').forEach(el=>el.onchange=()=>{let all={};try{all=JSON.parse(localStorage.getItem('basis-evidence-exclusions')||'{}')}catch{}const id=currentEvaluation().id,excluded=new Set(all[id]||[]);el.checked?excluded.delete(el.dataset.includeSuite):excluded.add(el.dataset.includeSuite);all[id]=[...excluded];localStorage.setItem('basis-evidence-exclusions',JSON.stringify(all));render()});
document.querySelectorAll('[data-review-attempt]').forEach(el=>el.onclick=()=>{const id=currentEvaluation().id,key=el.dataset.reviewAttempt;addModal('Review attempt',[{name:'accepted',label:'Meets acceptance criteria?',type:'select',options:[['no','No'],['yes','Yes']]},{name:'notes',label:'Review evidence and explanation',type:'textarea'},{name:'humanMinutes',label:'Human review and correction time (minutes)',type:'number',min:0,required:false},{name:'usageCost',label:'Actual provider cost ($), if known',type:'number',min:0,step:'any',required:false}],async v=>{try{await localRequest('review',{id,key,review:{accepted:v.accepted==='yes',notes:v.notes,humanMinutes:v.humanMinutes===''?null:Number(v.humanMinutes),usageCost:v.usageCost===''?null:Number(v.usageCost)}});await loadEvaluationHistory();render()}catch(error){showMessage(error.message)}})});
bindEvaluationProgress();if(bridgeReady)evaluationTimer=setTimeout(pollEvaluation,2500);
}

function pilotResults(){return title('03 / RESULTS','Pilot results','Review recorded attempts, outcomes, human effort, and evidence. These are user-provided observations.',`<button class="secondary" data-act="add-run">${icon('plus',16)} Record an observation</button>`)+`${s.runs.length?'':'<div class="empty"><b>No pilot results yet</b><p>This archive holds manually recorded observations. New automatic runs appear in Evaluation results.</p></div>'}<div class="panel"><div class="panelheading"><h3>Evidence log</h3><div><select data-filter="runs"><option>All</option>${s.platforms.map(p=>`<option ${filter===p.id?'selected':''} value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div></div><div class="table-scroll"><table><thead><tr><th>Task & platform</th><th>Accepted</th><th>Human time</th><th>Usage cost</th><th>Evidence</th><th></th></tr></thead><tbody>${s.runs.filter(r=>filter==='All'||r.platform===filter).map(r=>`<tr><td><b>${esc(platformName(r.platform))}</b><small>${esc(s.tasks.find(x=>x.id===r.task)?.name||r.task)}</small></td><td><span class="pill ${r.accepted?'pass':'fail'}">${r.accepted?'Accepted':'Not accepted'}</span></td><td>${f(r.humanMinutes)} min</td><td>${money(r.usageCost)}</td><td>${r.evidence?`<a href="${safeHref(r.evidence)}" target="_blank" rel="noopener noreferrer">Source ↗</a>`:'<span class="dim">Not linked</span>'}</td><td><button class="iconbtn" title="Delete record" aria-label="Delete run" data-act="delete-run" data-id="${esc(r.id)}">${icon('trash',15)}</button></td></tr>`).join('')}</tbody></table></div></div><div class="panel focus"><h3>Compare the evidence</h3><p class="muted">Evidence links support review; they do not automatically verify a result. Compare services after collecting representative attempts.</p><button class="primary" data-nav="compare">Compare measured results ${icon('chev',16)}</button></div>`;}

function compare(){const arr=scorePlatforms(s),choices=s.platforms.filter(p=>p.enabled);const selectedId=choices.some(p=>p.id===selected)?selected:choices[0]?.id;selected=selectedId;const chosen=arr.find(x=>x.id===selectedId);return title('05 / ANALYZE','Pilot comparison','Explore how each candidate performs on your workload. Recompute results as assumptions change.',`<div class="inlineactions"><button class="secondary" data-act="manage-platforms">${icon('settings',16)} Candidates</button><button class="secondary" data-nav="decision">Decision summary ${icon('chev',16)}</button></div>`)+`<div class="comparecontrols"><div class="pillgroup">${choices.map(p=>`<button class="${selectedId===p.id?'active':''}" data-platform="${p.id}">${esc(p.name)}</button>`).join('')}</div><span class="miniTag">Workload-normalized pilot data</span></div><div class="metrics">${stat(chosen?pct(chosen.success):'—','Accepted task rate','Weighted for your workload')}${stat(chosen?f(chosen.effort,0)+'m':'—','Human effort','Per accepted task')}${stat(chosen?money(chosen.fullCost):'—','Full cost','Per accepted task · modeled')}${stat(chosen?pct(chosen.coverage):'—','Workload coverage','Tested task-family share')}</div><div class="split"><div class="panel"><div class="panelheading"><h3>Quality by work type</h3><span class="miniTag">Pass rate</span></div>${TYPES.map((t,i)=>{const r=chosen?.byType[t];return `<div class="barrow"><div class="barlabel"><span>${t}</span><b>${pct(r?.success)}</b></div><div class="track"><span style="width:${r?.success==null?0:r.success*100}%;background:var(--c${i+1})"></span></div><small>${r?.n||0} trial records</small></div>`}).join('')}<div class="panelnote">Small samples are unstable. Empty categories are missing evidence, not zero performance.</div></div><div class="panel"><div class="panelheading"><h3>Cost sensitivity</h3><span class="miniTag">What if?</span></div><p class="muted">Adjust the blended hourly labor rate. All shown cost models update together.</p><div class="bigslider"><div class="rangevalue"><span>Hourly labor</span><strong id="rate-label">$${f(s.org.rate)}</strong></div><input type="range" min="20" max="250" step="5" data-range="org.rate" value="${s.org.rate}"></div><div class="costlist">${arr.map(m=>`<div class="costitem"><span>${esc(platformName(m.id))}</span><div class="costtrack"><i style="width:${m.fullCost!=null?Math.max(3,Math.min(100,m.fullCost/Math.max(...arr.map(x=>x.fullCost||0),1)*100)):0}%"></i></div><b>${money(m.fullCost)}</b></div>`).join('')}</div><p class="panelnote">Model includes measured per-attempt usage + labor + illustrative allocated platform overhead. Configure overhead in assumptions.</p></div></div><div class="panel"><div class="panelheading"><h3>All-candidate results</h3><button class="subtle" data-act="toggle-details">${details?'Hide scoring':'Show scoring method'} ${icon('down',15)}</button></div><div class="table-scroll"><table><thead><tr><th>Platform</th><th>Accepted</th><th>Effort / accepted</th><th>Cost / accepted</th><th>Gate</th><th>Evidence</th></tr></thead><tbody>${arr.map(m=>`<tr><td><b>${esc(platformName(m.id))}</b></td><td>${pct(m.success)}</td><td>${m.effort==null?'—':f(m.effort,0)+' min'}</td><td>${money(m.fullCost)}</td><td><span class="pill ${m.gate}">${m.gate}</span></td><td>${m.evidence.linked}/${m.evidence.total} linked</td></tr>`).join('')}</tbody></table></div>${details?`<div class="panelnote">Weights: ${Object.entries(s.weights).map(([k,v])=>`${k} ${v}`).join(' · ')}. Scores are relative exploratory indicators, not validated rankings. Missing work types and synthetic evidence disqualify candidates from a final recommendation.</div>`:''}</div>`}
function judge(){const discrepancy=s.judgments.filter(j=>j.scoreA!==j.scoreB).length;return title('06 / ASSURANCE','Review quality','LLM opinions are supplementary. Inspect conflicts, stability, and calibration before trusting subjective assessments.',`<button class="secondary" data-act="add-judgment">${icon('plus',16)} Add blind judgment</button>`)+`<div class="hero compact"><div class="hero-copy"><div class="hero-tag">${icon('shield',15)} INDEPENDENCE FIRST</div><h2>No model gets to pick its own winner.</h2><p>Blind labels, counterbalanced order, independent review and an auditable decision engine.</p></div><div class="integrity-symbol">${icon('scale',72)}</div></div><div class="metrics">${stat(s.judgments.length,'Recorded judgments','Blind assessment entries')}${stat(discrepancy,'Judge disagreements','Require adjudication')}${stat(s.judges.filter(j=>j.calibrated).length+'/'+s.judges.length,'Calibrated judges','Verified against human cases')}${stat('0','Auto overrides','The judge cannot bypass gates')}</div><div class="split"><div class="panel"><div class="panelheading"><h3>Assessment guardrails</h3></div>${[['eye-off','Mask vendor identity','Blind code evaluation where technically possible.'],['rotate','Counterbalance ordering','Review both A/B and B/A orderings.'],['shield','Run objective checks first','Tests and security outcomes outrank model preference.'],['finger','Version every decision','Preserve rubric, judge model, prompt, and reviewer action.']].map(([ic,t,d],i)=>`<div class="guard"><span class="guardnum">0${i+1}</span><span><b>${t}</b><small>${d}</small></span>${icon('check',16)}</div>`).join('')}</div><div class="panel"><div class="panelheading"><h3>Judge registry</h3></div>${s.judges.map(j=>`<div class="judgerow"><div class="avatar">${icon('brain',18)}</div><div><b>${esc(j.name)}</b><small>${esc(j.family)}</small></div><span class="pill ${j.calibrated?'pass':'unverified'}">${j.calibrated?'Calibrated':'Not calibrated'}</span></div>`).join('')}<div class="panelnote">Do not treat a multi-model vote as a guarantee of neutrality. Calibrate using independent, expert-reviewed code samples.</div></div></div><div class="panel"><div class="panelheading"><h3>Blind review records</h3></div>${s.judgments.length?`<div class="table-scroll"><table><thead><tr><th>Case</th><th>Judge A</th><th>Judge B</th><th>Reviewer verdict</th></tr></thead><tbody>${s.judgments.map(j=>`<tr><td>${esc(j.caseName)}</td><td>${j.scoreA}/5</td><td>${j.scoreB}/5</td><td>${esc(j.review||'Pending')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No judgment records yet. Add an assessment and independently calibrate it before using it as evidence.</div>'}</div>`}
function decisionPage(){const d=decision(s),arr=d.ranked;return title('07 / DECISION','Decision summary','Make a choice only when quality, governance, cost, and evidence withstand scrutiny.',`<div class="inlineactions"><button class="secondary" data-act="export">${icon('download',16)} Export study</button></div>`)+`<div class="hero decisionhero"><div class="hero-copy"><div class="hero-tag">${icon('scale',15)} REPRODUCIBLE DECISION ENGINE</div><h2>${esc(d.heading)}</h2><p>${esc(d.reason)}</p><span class="pill ${d.type==='insufficient'?'unverified':'pass'}">${d.type==='insufficient'?'Evidence required':d.type==='tie'?'Review required':'Conditional only'}</span></div><div class="integrity-symbol">${icon('target',72)}</div></div><div class="split"><div class="panel"><div class="panelheading"><h3>Readiness by platform</h3></div>${arr.map(m=>`<div class="readyrow"><span><b>${esc(platformName(m.id))}</b><small>${m.n} records · ${m.evidence.linked} linked · ${pct(m.coverage)} workload coverage</small></span><span class="pill ${m.eligible?'pass':m.gate==='fail'?'fail':'unverified'}">${m.eligible?'Eligible':m.gate==='fail'?'Blocked':'Not ready'}</span></div>`).join('')}</div><div class="panel"><div class="panelheading"><h3>What is needed next</h3></div>${[['shield','Verify mandatory controls','Attach security, legal and access-control evidence.'],['link','Source your test results','Replace demonstrations with auditable pilot records.'],['flask','Run balanced work samples','Expand difficult task types and track downstream defects.'],['brain','Calibrate subjective judges','Use human-reviewed references and bias checks.']].map(([ic,t,d])=>`<div class="guard"><span class="avatar">${icon(ic,16)}</span><span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div></div><div class="panel focus"><h3>Decision policy</h3><p class="muted">A vendor becomes eligible only when all mandatory requirements are marked pass, every active work type has pilot records, there are at least five recorded runs, at least 70% of those runs have evidence links, and the study is no longer marked as demonstration data. These minimums are prototype guardrails, not statistical proof of superiority.</p><button class="primary" data-act="mark-real">${s.meta.demo?'Review converting demo to real':'Study already marked as real'} ${icon('chev',16)}</button></div>`}
function technology(){const summary=documentSummary();return title('06 / OFFICIAL DOCUMENTATION','Tool catalog','Vendor capabilities, with primary-source links and explicit evidence status. Documentation is not an independent product test.',`<span class="miniTag">Reviewed ${reviewedOn}</span>`)+`<div class="metrics">${stat(summary.platforms,'Catalog entries','Named vendor configurations')}${stat(summary.documentedClaims,'Sourced claims','Vendor documentation only')}${stat(summary.independentlyVerifiedClaims,'Independently verified','Needs integration tests')}${stat(dimensions.length,'Capability groups','Unknown is not unsupported')}</div><div class="panel"><div class="panelheading"><h3>Documentation evidence</h3><small>Click each cited claim for the vendor source ↗</small></div><div class="tech-scroll"><table class="tech-table"><thead><tr><th>Capability</th>${s.platforms.filter(p=>p.enabled).map(p=>`<th>${esc(p.name)}<small>${esc(p.mode)}</small></th>`).join('')}</tr></thead><tbody>${dimensions.map(d=>`<tr><th>${icon(d.icon,16)} ${esc(d.label)}</th>${s.platforms.filter(p=>p.enabled).map(p=>{const cs=evidenceFor(p.id,d.id);return `<td>${cs.length?cs.map(c=>`<a target="_blank" rel="noopener noreferrer" href="${safeHref(c.source)}" title="Open official documentation"><span class="source-dot">● Documented ↗</span><small>${esc(c.claim)}</small></a>`).join(''):'<span class="unknown">? Not researched</span>'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="panelnote">“Documented” means a vendor currently describes the capability; it does not imply it was tested in your configuration. Unknown means not yet researched, not absent. Claims must be rechecked before procurement.</div></div><div class="split"><div class="panel"><div class="panelheading"><h3>How to use this evidence</h3></div><div class="guard"><span class="avatar">${icon('book')}</span><span><b>Read the claim</b><small>Open the primary source, confirm plan, model, version and restrictions.</small></span></div><div class="guard"><span class="avatar">${icon('flask')}</span><span><b>Verify in your environment</b><small>Run a controlled demonstration and record observations under Run tests → Record a result.</small></span></div></div><div class="panel"><div class="panelheading"><h3>Source health</h3></div><p class="muted">Last editorial review: ${reviewedOn}. Automated link checks run in GitHub Actions; live vendor content is not silently converted into approved claims.</p><p class="muted">Technical requirements remain governed by the mandatory controls in Set up → Services & criteria.</p><button class="secondary" data-nav="gates">Review requirements ${icon('chev',16)}</button></div></div>`;}
const localProviders=[
 {name:'Anthropic',secret:'ANTHROPIC_API_KEY'},
 {name:'OpenAI',secret:'OPENAI_API_KEY'},
 {name:'Cursor',secret:'CURSOR_API_KEY'}
];
const localRunners={claude:'ANTHROPIC_API_KEY',codex:'OPENAI_API_KEY',cursor:'CURSOR_API_KEY',opencode:null};
let bridgeReady=false,bridgeToken='',localStatus=null;
function selectedLocalServices(){return s.platforms.filter(p=>p.enabled&&Object.hasOwn(localRunners,p.id));}
function neededProviders(){const needed=new Set(selectedLocalServices().map(serviceKey));return localProviders.filter(p=>needed.has(p.secret));}
function localConnection(){return `<section class="connection-strip" aria-label="Local connection"><div class="connection-state">${icon('link',16)}<span>Local connection</span><span class="pill unverified" id="bridge-label" role="status">Checking…</span></div><div class="connection-actions"><a class="secondary" id="open-local-app" href="http://127.0.0.1:8765/" hidden>Open local app ${icon('link',14)}</a><button class="iconbtn" id="bridge-recheck" aria-label="Check connection" title="Check connection">${icon('rotate',16)}</button><button class="inlinebtn" data-act="connection-help">Connection help</button></div><p id="local-connection-note" role="status" hidden></p></section>`;}
function credentialPanel(){const providers=neededProviders();return localConnection()+`<section class="panel credentials-panel"><div class="panelheading"><h3>Provider keys</h3><button class="inlinebtn" data-nav="gates">Change services</button></div><div class="local-credentials">${providers.map(p=>`<div class="local-credential"><div class="credential-heading"><h3>${esc(p.name)}</h3><span class="pill unverified" data-key-status="${p.secret}">Checking…</span></div><div class="credential-entry"><input type="password" aria-label="${esc(p.name)} API key" autocomplete="new-password" data-local-key="${p.secret}" placeholder="API key" disabled><button class="secondary" data-save-local="${p.secret}" disabled>Save key</button></div><p role="status" class="credential-feedback" data-key-feedback="${p.secret}"></p></div>`).join('')||'<p class="muted">Select a service to add its key.</p>'}</div><div class="credentials-footer"><span class="muted">${icon('shield',14)} ${isLocalApp()?'Stored securely on this device':'Keys stay in memory until transferred'}</span><button class="primary" data-act="continue-local">${isLocalApp()?'Continue':'Continue locally'} ${icon('chev',16)}</button></div></section>`;}

function settings(){return title('SETTINGS','Settings','Manage saved credentials and this browser’s evaluation data.')+credentialPanel()+`<section class="panel"><h3>Local evaluation data</h3><p class="muted">Refreshing preserves this browser’s evaluation. Export your study before resetting if you need to keep it. Resetting does not delete OS credentials or saved local evaluations.</p><div class="inlineactions"><button class="secondary" data-act="export">${icon('download',16)} Export study</button><button class="secondary" data-act="reset">${icon('rotate',16)} Reset evaluation</button></div></section>`;}
async function localRequest(route,data={}){const response=await fetch('/api/local/'+route,{method:'POST',headers:{'Content-Type':'application/json','X-Basis-Token':bridgeToken},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Local companion request failed.');return result;}
function updateLocalStatus(){
 document.querySelectorAll('[data-key-status]').forEach(el=>{const ready=localStatus?.configured?.[el.dataset.keyStatus],pending=pendingKeys.has(el.dataset.keyStatus);el.textContent=!isLocalApp()?(pending?'Ready to transfer':'Not provided'):!bridgeReady||localStatus?.credentialError?'Not checked':ready?'Configured':'Not configured';el.className='pill '+(ready||pending?'pass':'unverified');});
 document.querySelectorAll('[data-local-key]').forEach(el=>{el.disabled=isLocalApp()&&(!bridgeReady||!!localStatus?.credentialError);el.placeholder=localStatus?.configured?.[el.dataset.localKey]?'Enter replacement key':pendingKeys.has(el.dataset.localKey)?'Key ready to transfer':'API key';});
 document.querySelectorAll('[data-save-local]').forEach(el=>{el.disabled=isLocalApp()&&(!bridgeReady||!!localStatus?.credentialError);el.textContent=!isLocalApp()?'Use key':localStatus?.configured?.[el.dataset.saveLocal]?'Replace key':'Save key';});
}
async function checkBridge(){
 try{if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('Open Basis through the local companion.');const response=await fetch('/api/health',{cache:'no-store'}),health=await response.json();if(health.service!=='basis-local-companion')throw Error('Start the updated local companion.');bridgeToken=health.token;localStatus=await localRequest('status');bridgeReady=true;
 if($('#bridge-label')){$('#bridge-label').textContent='Connected';$('#bridge-label').className='pill pass';}
 if($('#local-connection-note')){$('#local-connection-note').textContent=localStatus.credentialError?'Credential store unavailable. See Connection help.':'';$('#local-connection-note').hidden=!localStatus.credentialError;}if($('#open-local-app'))$('#open-local-app').hidden=true;
 }catch(error){bridgeReady=false;localStatus=null;if($('#bridge-label')){$('#bridge-label').textContent='Disconnected';$('#bridge-label').className='pill unverified';}if($('#local-connection-note')){$('#local-connection-note').textContent='Connect locally to manage keys and run evaluations.';$('#local-connection-note').hidden=false;}if($('#open-local-app'))$('#open-local-app').hidden=['localhost','127.0.0.1'].includes(location.hostname);}
 updateLocalStatus();
 paintModelFields();
 if(bridgeReady)await Promise.all(selectedLocalServices().map(p=>loadServiceModels(p)));
}
function bindCredentialFields(){
 if(!isLocalApp())document.querySelectorAll('[data-local-key]').forEach(input=>input.oninput=()=>{const value=input.value.trim(),key=input.dataset.localKey;if(value.length>=8&&value.length<=8000&&!/[\r\n\x00]/.test(value))pendingKeys.set(key,value);else pendingKeys.delete(key);updateLocalStatus()});
 document.querySelectorAll('[data-save-local]').forEach(button=>button.onclick=async()=>{const name=button.dataset.saveLocal,row=button.closest('.service-key-field,.local-credential'),input=row.querySelector('[data-local-key]'),feedback=row.querySelector('[data-key-feedback]'),value=input.value.trim();if(value.length<8||value.length>8000||/[\r\n\x00]/.test(value)){feedback.textContent='Enter a valid API key.';return}input.value='';button.disabled=true;
 if(!isLocalApp()){pendingKeys.set(name,value);feedback.textContent='Ready to transfer.';updateLocalStatus();return}
 try{invalidateModels(name);await localRequest('credentials',{secret:name,value});feedback.textContent='Key saved.';await checkBridge();}catch(error){feedback.textContent=error.message;button.disabled=false;}});
}
function bindLocal(){checkBridge();$('#bridge-recheck')?.addEventListener('click',checkBridge);bindCredentialFields();}
function benchmarks(){
 let rows=[];try{rows=JSON.parse(localStorage.getItem('basis-community-benchmark-imports')||'[]')}catch{}
 return title('02 / RUN EVALUATION','External benchmarks','Standard, externally maintained suites. Pick a benchmark, run its official harness, and bring the evidence back to Basis.')+
 `<div class="benchmark-grid">${BENCHMARKS.map((b,i)=>`<article class="panel benchmark-tile"><div class="panelheading"><h3>${esc(b.name)}</h3><span class="miniTag">Official suite</span></div><div class="muted">${esc(b.category)} · ${esc(b.difficulty)}</div><p>${esc(b.note)}</p><div class="panelnote">${esc(b.runner)}<br>${esc(b.runtime)}</div><div class="bench-actions"><a href="${b.setup}" target="_blank" rel="noopener noreferrer" class="secondary">Run instructions ↗</a><a href="${b.source}" target="_blank" rel="noopener noreferrer" class="textaction" aria-label="Official source ${esc(b.name)}">Source ↗</a></div></article>`).join('')}</div>`+
 `<div class="panel"><div class="panelheading"><h3>Import standardized evidence</h3><span class="miniTag">Not automatically verified</span></div><p class="muted">Run the official benchmark harness externally; normalize its authentic task outcomes to the Basis v1 report schema. Importing does not certify that the claimed agent or harness was used.</p><div class="bench-actions"><button class="primary" data-act="import-benchmark">${icon('upload',16)} Import benchmark report</button><button class="secondary" data-act="download-benchmark-template">${icon('download',16)} Download report template</button></div><input type="file" id="benchmark-file" accept="application/json,.json" hidden><div class="panelnote">Scores are only comparable for exactly matching dataset revisions, harness revisions, evaluation conditions and task sets. Existing toy-agent runs are not community benchmark runs.</div></div>`+
 (rows.length?`<div class="panel"><div class="panelheading"><h3>Imported reports</h3><span class="miniTag">Self-reported · Unverified</span></div><div class="table-scroll"><table><thead><tr><th>Benchmark</th><th>Agent / model</th><th>Resolved</th><th>Tasks</th><th>Evidence</th></tr></thead><tbody>${rows.map(r=>{const sum=summarizeReport(r);return `<tr><td>${esc(BENCHMARKS.find(b=>b.id===r.benchmarkId)?.name)}</td><td>${esc(r.agent)} / ${esc(r.model)}</td><td>${sum.resolved} / ${sum.total}</td><td>${sum.total}</td><td>Unverified import</td></tr>`}).join('')}</tbody></table></div></div>`:`<div class="panel"><p class="muted">No benchmark results imported yet. No fabricated scores are shown.</p></div>`);
}
// Keep native selects for form submission; use one shared, keyboard-accessible menu.
let activeDropdown = null;
function closeDropdown() {
 if (!activeDropdown) return;
 activeDropdown.menu.remove();
 activeDropdown.trigger.setAttribute('aria-expanded','false');
 activeDropdown.trigger.removeAttribute('aria-activedescendant');
 activeDropdown = null;
}
document.addEventListener('pointerdown',e=>{
 if(activeDropdown&&!activeDropdown.wrapper.contains(e.target)&&!activeDropdown.menu.contains(e.target))closeDropdown();
});
document.addEventListener('focusin',e=>{
 if(activeDropdown&&!activeDropdown.wrapper.contains(e.target)&&!activeDropdown.menu.contains(e.target))closeDropdown();
});
window.addEventListener('resize',closeDropdown);
window.addEventListener('scroll',e=>{
 if(activeDropdown&&!activeDropdown.menu.contains(e.target))activeDropdown.position();
},true);
let dropdownSequence=0;
function enhanceSelects(root=document) {
 root.querySelectorAll('select:not([data-enhanced])').forEach((select,index)=>{
  select.dataset.enhanced='true';
  const id=`dropdown-${++dropdownSequence}`;
  const wrapper=document.createElement('div');wrapper.className='dropdown';
  const label=select.labels?.[0]?.cloneNode(true);
  label?.querySelectorAll('select').forEach(node=>node.remove());
  const optionLabel=option=>select.classList.contains('status')?option.textContent.replace(/^[?✓×]\s*/, ''):option.textContent;
  const name=select.getAttribute('aria-label')||label?.textContent.trim()||(select.dataset.filter?'Filter pilot runs':'Choose an option');
  const trigger=document.createElement('button');trigger.type='button';trigger.id=id;
  trigger.className='dropdown-trigger '+select.className;
  trigger.setAttribute('role','combobox');trigger.setAttribute('aria-label',name);
  trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  trigger.setAttribute('aria-controls',id+'-list');trigger.disabled=select.disabled;
  trigger.dataset.tone=select.classList.contains('status')?select.value:'';
  trigger.dataset.placeholder=String(select.dataset.placeholderValue===select.value);
  const value=document.createElement('span');value.className='dropdown-value';value.id=id+'-value';trigger.setAttribute('aria-describedby',value.id);value.textContent=select.selectedOptions[0]?optionLabel(select.selectedOptions[0]):'Choose an option';
  trigger.append(value);trigger.insertAdjacentHTML('beforeend',icon('down',15));
  select.before(wrapper);wrapper.append(select,trigger);select.hidden=true;
  let search='',searchTime=0;
  function open(direction=1) {
   closeDropdown();
   const options=Array.from(select.options);
   const enabled=options.map((o,i)=>o.disabled?-1:i).filter(i=>i>=0);
   if(!enabled.length)return;
   const menu=document.createElement('div');menu.className='dropdown-menu';menu.id=id+'-list';
   menu.setAttribute('role','listbox');menu.setAttribute('aria-label',name);
   const state={wrapper,trigger,menu,index:enabled.includes(select.selectedIndex)?select.selectedIndex:enabled[direction>0?0:enabled.length-1]};
   function highlight(index) {
    state.index=index;
    menu.querySelectorAll('[role=option]').forEach((node,i)=>node.classList.toggle('highlighted',i===index));
    trigger.setAttribute('aria-activedescendant',id+'-option-'+index);
    const item=menu.children[index];if(item){if(item.offsetTop<menu.scrollTop)menu.scrollTop=item.offsetTop;else if(item.offsetTop+item.offsetHeight>menu.scrollTop+menu.clientHeight)menu.scrollTop=item.offsetTop+item.offsetHeight-menu.clientHeight;}
   }
   function choose(index) {
    if(options[index].disabled)return;
    closeDropdown();select.value=options[index].value;
    value.textContent=optionLabel(options[index]);
    trigger.dataset.tone=select.classList.contains('status')?select.value:'';
  trigger.dataset.placeholder=String(select.dataset.placeholderValue===select.value);
    select.dispatchEvent(new Event('change',{bubbles:true}));
    document.getElementById(id)?.focus({preventScroll:true});
   }
   options.forEach((option,index)=>{
    const item=document.createElement('div');item.id=id+'-option-'+index;item.className='dropdown-option';
    item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));
    if(option.disabled)item.setAttribute('aria-disabled','true');
    const text=document.createElement('span');text.textContent=optionLabel(option);item.append(text);if(select.classList.contains('status'))item.dataset.tone=option.value;
    item.insertAdjacentHTML('beforeend',icon('check',15));
    item.onpointermove=()=>{if(!option.disabled)highlight(index)};
    item.onpointerdown=e=>e.preventDefault();
    item.onclick=e=>{e.preventDefault();choose(index)};
    menu.append(item);
   });
   document.body.append(menu);
   function position(){
   const rect=trigger.getBoundingClientRect();if(rect.bottom<0||rect.top>innerHeight){closeDropdown();return}
   const below=innerHeight-rect.bottom-12,above=rect.top-12;
   const upward=below<Math.min(menu.scrollHeight,220)&&above>below;
   const available=Math.max(60,upward?above:below);
   menu.style.maxHeight=Math.min(280,available)+'px';
   menu.style.width=Math.min(rect.width,innerWidth-24)+'px';
   menu.style.left=Math.max(12,Math.min(rect.left,innerWidth-menu.offsetWidth-12))+'px';
   menu.style.top=(upward?Math.max(6,rect.top-menu.offsetHeight-6):rect.bottom+6)+'px';
   }
   state.position=position;activeDropdown=state;state.highlight=highlight;state.choose=choose;state.enabled=enabled;position();
   trigger.setAttribute('aria-expanded','true');highlight(state.index);
  }
  trigger.onclick=e=>{e.preventDefault();if(activeDropdown?.trigger===trigger)closeDropdown();else open()};
  trigger.onkeydown=e=>{
   const state=activeDropdown?.trigger===trigger?activeDropdown:null;
   if(e.key==='Tab'){closeDropdown();return}
   if(e.key==='Escape'){e.preventDefault();closeDropdown();return}
   if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(e.key)){
    e.preventDefault();
    if(!state){open(e.key==='ArrowUp'?-1:1);if(activeDropdown&&(e.key==='Home'||e.key==='End'))activeDropdown.highlight(activeDropdown.enabled[e.key==='Home'?0:activeDropdown.enabled.length-1]);return}
    if(e.key==='Enter'||e.key===' '){state.choose(state.index);return}
    const pos=state.enabled.indexOf(state.index);
    const next=e.key==='Home'?0:e.key==='End'?state.enabled.length-1:(pos+(e.key==='ArrowDown'?1:-1)+state.enabled.length)%state.enabled.length;
    state.highlight(state.enabled[next]);return;
   }
   if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){
    e.preventDefault();if(!state)open();
    const current=activeDropdown;if(!current)return;
    const now=Date.now();search=now-searchTime>700?e.key:search+e.key;searchTime=now;
    const found=current.enabled.find(i=>select.options[i].textContent.trim().toLowerCase().startsWith(search.toLowerCase()));
    if(found!==undefined)current.highlight(found);
   }
  };
 });
}

// Shared numeric controls retain native keyboard, stepping, and form semantics.
function enhanceNumberInputs(root=document) {
 root.querySelectorAll('input[type="number"]:not([data-stepper])').forEach((input,index)=>{
  input.dataset.stepper='true';
  const key=input.id||input.dataset.path||input.dataset.weight||input.name||String(index);
  const label=input.labels?.[0]?.textContent.trim()||input.getAttribute('aria-label')||'value';
  const wrap=document.createElement('span');wrap.className='number-field';wrap.dataset.numberKey=key;
  input.before(wrap);wrap.append(input);
  const controls=document.createElement('span');controls.className='number-controls';wrap.append(controls);
  for(const [direction,name] of [[1,'Increase'],[-1,'Decrease']]) {
   const button=document.createElement('button');button.type='button';button.className='number-step';
   button.dataset.direction=direction;button.setAttribute('aria-label',`${name} ${label}`);
   button.innerHTML=`<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${direction===1?'m6 15 6-6 6 6':'m6 9 6 6 6-6'}"/></svg>`;
   button.disabled=input.disabled||input.readOnly;
   button.onmousedown=e=>e.preventDefault();
   button.onclick=()=>{
    const before=input.value;
    direction===1?input.stepUp():input.stepDown();
    if(input.value!==before){input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}
    const current=[...document.querySelectorAll('.number-field')].find(el=>el.dataset.numberKey===key);
    current?.querySelector(`[data-direction="${direction}"]`)?.focus();
   };
   controls.append(button);
  }
 });
}

// Native dialog supplies focus containment and inert background; all visuals belong to Basis.
function messageDialog(message,{title='Check your input',confirmLabel='Continue',confirmation=false}={}) {
 closeDropdown();
 const previous=document.activeElement;
 const dialog=document.createElement('dialog');dialog.className='message-dialog';
 dialog.setAttribute('aria-labelledby','message-title');dialog.setAttribute('aria-describedby','message-body');
 dialog.innerHTML=`<div class="modalhead"><h2 id="message-title">${esc(title)}</h2><button type="button" class="iconbtn" data-dismiss aria-label="Close">${icon('cross',18)}</button></div><p id="message-body">${esc(message)}</p><div class="modalbuttons">${confirmation?'<button type="button" class="secondary" data-dismiss autofocus>Cancel</button>':''}<button type="button" class="primary" data-accept ${confirmation?'':'autofocus'}>${esc(confirmation?confirmLabel:'Got it')}</button></div>`;
 document.body.append(dialog);
 return new Promise(resolve=>{
  dialog.addEventListener('close',()=>{const accepted=dialog.returnValue==='accept';dialog.remove();if(previous?.isConnected)previous.focus();resolve(accepted);},{once:true});
  dialog.querySelectorAll('[data-dismiss]').forEach(button=>button.onclick=()=>dialog.close());
  dialog.querySelector('[data-accept]').onclick=()=>dialog.close('accept');
  dialog.addEventListener('keydown',event=>{
   if(event.key!=='Tab')return;
   const buttons=[...dialog.querySelectorAll('button:not(:disabled)')];
   event.preventDefault();
   const index=buttons.indexOf(document.activeElement);
   buttons[(index+(event.shiftKey?-1:1)+buttons.length)%buttons.length].focus();
  });
  dialog.showModal();
 });
}
function confirmDialog(message,options={}) {return messageDialog(message,{...options,confirmation:true});}
function showMessage(message) {return messageDialog(message);}

