function addModal(name,fields,callback){const wrap=document.createElement('div');wrap.className='modalback';wrap.innerHTML=`<form class="modal"><div class="modalhead"><h2>${esc(name)}</h2><button type="button" class="iconbtn" data-close aria-label="Close">${icon('cross',18)}</button></div>${fields.map(x=>`<label>${x.label}${x.type==='select'?`<select name="${x.name}">${x.options.map(v=>`<option value="${esc(v[0])}" ${String(x.value)===String(v[0])?'selected':''}>${esc(v[1])}</option>`).join('')}</select>`:x.type==='textarea'?`<textarea name="${x.name}" ${x.required===false?'':'required'}>${esc(x.value??'')}</textarea>`:`<input name="${x.name}" type="${x.type||'text'}" ${x.step?`step="${esc(x.step)}"`:''} ${x.required===false?'':'required'} ${x.min!=null?`min="${x.min}"`:''} value="${esc(x.value??'')}">`}</label>`).join('')}<div class="modalbuttons"><button type="button" data-close class="secondary">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;document.body.append(wrap);enhanceSelects(wrap);enhanceNumberInputs(wrap);wrap.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{closeDropdown();wrap.remove()});wrap.onclick=e=>{if(e.target===wrap){closeDropdown();wrap.remove()}};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();const obj=Object.fromEntries(new FormData(e.target));callback(obj);wrap.remove();save();render();};wrap.querySelector('input:not([hidden]),button[role=combobox],textarea')?.focus();}
